import { Streamlit, StreamlitComponentBase, withStreamlitConnection } from "streamlit-component-lib"
import React, { ReactNode, useEffect } from "react"
import { createTheme } from '@mui/material/styles';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Stack from '@mui/material/Stack';
import { ThemeProvider } from "@emotion/react";
import { Box } from '@mui/system';

let state = "idle"

const ImageButton = ({ args, disabled }: any) => {
  useEffect(() => {
    Streamlit.setFrameHeight()

    if (state === "clicked") {
      state = "reset"
    }

    else if (state === "reset") {
      Streamlit.setComponentValue(false)
      state = "idle"
    }
  })

  const Theme = createTheme({
    palette: {
      primary: {
        main: args.color,  // Example: '#0052cc'
      },
    }
  })

  const handleClick = () => {
    Streamlit.setComponentValue(true)
    state = "clicked"
  }

  const image = 'data:image/gif;base64,' + args.image

  if (args.text === "") {
    return (
      <Stack spacing={2} direction="row" width={args.width} height={args.width} padding={0}>
        <ThemeProvider theme={Theme}>
          <Button style = {{ height: args.width, width: args.width }} onClick={handleClick} variant={args.variant}><img src={image} alt = "Button" width = {args.width} height = {args.width}/></Button>
        </ThemeProvider>
      </Stack>
      )  
  }

  return (
    <ThemeProvider theme={Theme}>
      <Box width={args.width} height={args.width} alignItems={"center"} padding={"0px !important"}>
        <Button style = {{ height: args.width, width: args.width, padding: 0 }} onClick={handleClick} variant={args.variant}>{args.text}</Button>
      </Box>
    </ThemeProvider>
    )
}

export default withStreamlitConnection(ImageButton)
